def OPT_KD_bruteforce(sigma, C, W):
    n=len(W)
    best=None
    for r in range(n+1):
        for S in combinations(range(n), r):
            val = e(list(C)+[W[i] for i in S])
            best = val if best is None else (min(best,val) if sigma==1 else max(best,val))
    return best if best is not None else e(C)

def OPT_KD_closedform(sigma, C, W):
    # exactly the DEL_KD/KEEP_KD recursion of Gap 2's proof
    if not W:
        return e(C)
    w1 = W[0]; rest = W[1:]
    DEL_KD = OPT_KD_closedform(sigma, C, rest)
    h = sum(1 for c in C if c > w1)
    Chi = [c for c in C if c > w1]
    Clo = [c for c in C if c <= w1]
    inner = OPT_KD_closedform(sigma*((-1)**(h+1)), Clo, rest)
    KEEP_KD = e(Chi) + ((-1)**h)*F(w1) + ((-1)**(h+1))*inner
    return min(DEL_KD,KEEP_KD) if sigma==1 else max(DEL_KD,KEEP_KD)

