import itertools
from fractions import Fraction as F

def e(multiset):
    s = sorted(multiset, reverse=True)
    total = F(0)
    sign = 1
    for x in s:
        total += sign*F(x)
        sign *= -1
    return total

def all_selections(W):
    """W: list of values (with positions). Yield (K,D,M) as (list kept, list deleted, list of matched pairs (value diffs))
       enumerate all ways to partition indices of W into: kept singleton, deleted singleton, matched pairs (any two indices, order doesn't matter beyond diff = larger-smaller).
    """
    n = len(W)
    idx = list(range(n))
    # We need all partitions of idx into: some kept as singles, some deleted as singles, some paired up (unordered pairs)
    # This is a classic recursive enumeration.
    def rec(remaining):
        if not remaining:
            yield []
            return
        first = remaining[0]
        rest = remaining[1:]
        # option: kept
        for tail in rec(rest):
            yield [('K', first)] + tail
        # option: deleted
        for tail in rec(rest):
            yield [('D', first)] + tail
        # option: paired with any other remaining element
        for j in range(len(rest)):
            partner = rest[j]
            new_rest = rest[:j] + rest[j+1:]
            for tail in rec(new_rest):
                yield [('M', first, partner)] + tail
    yield from rec(idx)

def opt_sigma(C, W, sigma):
    """C: list of background values. W: list of values (list, not necessarily sorted but we'll just use values).
       sigma = +1 minimize, -1 maximize.
    """
    best = None
    best_witness = None
    for sel in all_selections(W):
        vals = list(C)
        matched_info = []
        for item in sel:
            if item[0]=='K':
                vals.append(W[item[1]])
            elif item[0]=='D':
                pass
            elif item[0]=='M':
                i,j = item[1], item[2]
                a,b = W[i], W[j]
                d = abs(a-b)
                vals.append(d)
                matched_info.append((i,j))
        val = e(vals)
        if best is None or (sigma==1 and val<best) or (sigma==-1 and val>best):
            best = val
            best_witness = sel
        elif val==best:
            pass
    return best, best_witness

def opt_kd_sigma(C, W, sigma):
    best = None
    n = len(W)
    for mask in range(1<<n):
        vals = list(C)
        for i in range(n):
            if mask & (1<<i):
                vals.append(W[i])
        val = e(vals)
        if best is None or (sigma==1 and val<best) or (sigma==-1 and val>best):
            best = val
    return best

def witness_matches(sel, idx):
    for item in sel:
        if item[0]=='M' and (item[1]==idx or item[2]==idx):
            return True
    return False

