from fractions import Fraction as F

def e(multiset):
    s = sorted(multiset, reverse=True)
    total = F(0)
    sign = 1
    for x in s:
        total += sign * F(x)
        sign = -sign
    return total

def all_selections(n):
    """Yield selections over index set range(n) as list of ('K',i)/('D',i)/('M',i,j)."""
    idx = list(range(n))
    def rec(remaining):
        if not remaining:
            yield []
            return
        first = remaining[0]
        rest = remaining[1:]
        for tail in rec(rest):
            yield [('K', first)] + tail
        for tail in rec(rest):
            yield [('D', first)] + tail
        for pos, j in enumerate(rest):
            new_rest = rest[:pos] + rest[pos+1:]
            for tail in rec(new_rest):
                yield [('M', first, j)] + tail
    yield from rec(idx)

def OPT_sigma(C, W, sigma, return_witnesses=False):
    n = len(W)
    best = None
    witnesses = []
    for sel in all_selections(n):
        vals = list(C)
        for item in sel:
            if item[0] == 'K':
                vals.append(W[item[1]])
            elif item[0] == 'D':
                pass
            else:
                a, b = W[item[1]], W[item[2]]
                vals.append(abs(a-b))
        val = e(vals)
        if best is None or (sigma == 1 and val < best) or (sigma == -1 and val > best):
            best = val
