from fractions import Fraction
from itertools import combinations

def e(sorted_desc):
    """alternating sum of a sorted-descending list."""
    s = 0
    sign = 1
    for x in sorted_desc:
        s += sign * x
        sign = -sign
    return s

def all_selections(W):
    """Yield all lists representing (kept values + matched differences) for every
    valid Delete/Keep/Match selection of the list W (as a plain python list,
    order doesn't matter for correctness, only for recursion bookkeeping)."""
    if not W:
        yield []
        return
    w = W[0]
    rest = W[1:]
    # delete w
    for sel in all_selections(rest):
        yield sel
    # keep w
    for sel in all_selections(rest):
        yield sel + [w]
    # match w with some other element in rest
    for i in range(len(rest)):
        w2 = rest[i]
        rest2 = rest[:i] + rest[i+1:]
        for sel in all_selections(rest2):
            yield sel + [abs(w - w2)]

def OPT(sigma, B, W):
    """sigma-optimal value of e(B U selection(W)). sigma=+1 minimize, -1 maximize."""
    best = None
    for sel in all_selections(W):
        full = sorted(list(B) + sel, reverse=True)
        val = e(full)
        if best is None:
            best = val
        else:
            if sigma == 1:
                best = min(best, val)
            else:
                best = max(best, val)
    return best

def OPT_witnesses(sigma, B, W):
    """return (optimal value, list of all optimal selections achieving it)"""
    best = None
    witnesses = []
    for sel in all_selections(W):
        full = sorted(list(B) + sel, reverse=True)
        val = e(full)
        if best is None or (sigma == 1 and val < best) or (sigma == -1 and val > best):
            best = val
            witnesses = [sel]
        elif val == best:
            witnesses.append(sel)
    return best, witnesses

