from fractions import Fraction as F
import itertools, random

def e_sorted(vals):
    v = sorted(vals, reverse=True)
    s = F(0)
    for i,x in enumerate(v):
        s += x if i%2==0 else -x
    return s

def all_selections(Z):
    """Z: list of Fractions (positions distinguishable). Yield (Kset_vals, Mvals) as tuple:
    returns list of (multiset_of_active_values,) i.e. K-values + |zi-zj| for matches, D dropped.
    We enumerate over subsets of positions partitioned into K, D, and matched pairs."""
    n = len(Z)
    idx = list(range(n))
    # recursive: process positions in order; for position 0, choose D, K, or match with some later j
    def rec(remaining):
        if not remaining:
            yield []
            return
        i = remaining[0]
        rest = remaining[1:]
        # Delete i
        for tail in rec(rest):
            yield tail
        # Keep i
        for tail in rec(rest):
            yield [('K', Z[i])] + tail
        # Match i with some j in rest
        for j in rest:
            rest2 = [x for x in rest if x != j] if rest.count(j)==1 else rest[:]  # positions unique so fine
            rest2 = [x for x in rest if x != j]
            for tail in rec(rest2):
                yield [('M', abs(Z[i]-Z[j]))] + tail
    for sel in rec(idx):
        yield sel

def OPT_sigma(B, Z, sigma):
    best = None
    bestsels = []
    for sel in all_selections(Z):
        vals = list(B) + [v for (_,v) in sel]
        val = e_sorted(vals)
        if best is None:
            best = val; bestsels=[sel]
        else:
            if sigma==1:
                if val < best:
                    best = val; bestsels=[sel]
                elif val==best:
                    bestsels.append(sel)
            else:
                if val > best:
                    best = val; bestsels=[sel]
                elif val==best:
                    bestsels.append(sel)
    return best, bestsels

def sel_to_multiset(sel):
    return [v for (_,v) in sel]

